//! Generators of the named groups, as permutations of {0, ..., n-1}.
//!
//! The Mathieu groups M11, M12, M23 and M24 are generated by the permutations given in Conway and Sloane,
//! *Sphere Packings, Lattices and Groups*, ch. 10-11, and Dixon and Mortimer, *Permutation Groups*, 6.7 (an
//! 11-cycle or 23-cycle with an element normalising a subgroup of it, and for M12, M24 an involution exchanging
//! the extra point); M22 is the stabiliser of a point in M23, M21 that of two. The orders 7920, 95040, 443520,
//! 10200960 and 244823040 are checked by the tests.
use crate::perm::Perm;

/// The permutation of degree n with the given cycles (1-based points).
pub fn from_cycles(n: usize, cs: &[&[u32]]) -> Perm {
    let mut p: Perm = (0..n as u32).collect();
    for c in cs {
        for k in 0..c.len() {
            p[c[k] as usize - 1] = c[(k + 1) % c.len()] - 1;
        }
    }
    p
}

fn cycle(n: usize, from: u32, to: u32) -> Perm {
    let c: Vec<u32> = (from..=to).collect();
    from_cycles(n, &[&c])
}

pub fn symmetric(k: usize) -> (usize, Vec<Perm>) {
    if k < 2 {
        return (k, Vec::new());
    }
    (k, vec![from_cycles(k, &[&[1, 2]]), cycle(k, 1, k as u32)])
}

pub fn alternating(k: usize) -> (usize, Vec<Perm>) {
    if k < 3 {
        return (k, Vec::new());
    }
    let long = if k % 2 == 1 { cycle(k, 1, k as u32) } else { cycle(k, 2, k as u32) };
    (k, vec![from_cycles(k, &[&[1, 2, 3]]), long])
}

pub fn cyclic(k: usize) -> (usize, Vec<Perm>) {
    if k < 2 {
        return (k, Vec::new());
    }
    (k, vec![cycle(k, 1, k as u32)])
}

/// The dihedral group of order 2k: the symmetries of a k-gon (k >= 3); D_1 = C_2 on 2 points, D_2 the Klein
/// four-group on 4 points.
pub fn dihedral(k: usize) -> (usize, Vec<Perm>) {
    match k {
        0 => (0, Vec::new()),
        1 => (2, vec![from_cycles(2, &[&[1, 2]])]),
        2 => (4, vec![from_cycles(4, &[&[1, 2], &[3, 4]]), from_cycles(4, &[&[1, 3], &[2, 4]])]),
        _ => {
            let mut refl: Perm = (0..k as u32).collect();
            for x in 1..k {
                refl[x] = (k - x) as u32;
            }
            (k, vec![cycle(k, 1, k as u32), refl])
        }
    }
}

/// The direct product of cyclic groups of the given orders, on consecutive blocks of points.
pub fn abelian(orders: &[usize]) -> (usize, Vec<Perm>) {
    let n: usize = orders.iter().filter(|&&o| o > 1).sum();
    let mut gens = Vec::new();
    let mut at = 1u32;
    for &o in orders {
        if o > 1 {
            gens.push(cycle(n, at, at + o as u32 - 1));
            at += o as u32;
        }
    }
    (n, gens)
}

/// Generators of the Mathieu group M_k for k = 11, 12, 23, 24 (M22 and M21 are stabilisers in M23).
pub fn mathieu(k: usize) -> Option<(usize, Vec<Perm>)> {
    let m11b: &[&[u32]] = &[&[3, 7, 11, 8], &[4, 10, 5, 6]];
    let m23b: &[&[u32]] = &[&[3, 17, 10, 7, 9], &[4, 13, 14, 19, 5], &[8, 18, 11, 12, 23], &[15, 20, 22, 21, 16]];
    match k {
        11 => Some((11, vec![cycle(11, 1, 11), from_cycles(11, m11b)])),
        12 => Some((
            12,
            vec![
                cycle(12, 1, 11),
                from_cycles(12, m11b),
                from_cycles(12, &[&[1, 12], &[2, 11], &[3, 6], &[4, 8], &[5, 9], &[7, 10]]),
            ],
        )),
        23 => Some((23, vec![cycle(23, 1, 23), from_cycles(23, m23b)])),
        24 => Some((
            24,
            vec![
                cycle(24, 1, 23),
                from_cycles(24, m23b),
                from_cycles(
                    24,
                    &[&[1, 24], &[2, 23], &[3, 12], &[4, 16], &[5, 18], &[6, 10], &[7, 20], &[8, 14], &[9, 21], &[11, 17], &[13, 22], &[15, 19]],
                ),
            ],
        )),
        _ => None,
    }
}
